import { Hono } from 'hono';

type Env={Bindings:{DB:D1Database;AI:any;ALLOWED_ORIGINS:string;SESSION_SECRET:string;CLOUDINARY_CLOUD_NAME:string;CLOUDINARY_API_KEY:string;CLOUDINARY_API_SECRET:string;ADMIN_SETUP_KEY:string}};
const app=new Hono<Env>();
const json=(data:unknown,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json'}});
const now=()=>new Date().toISOString();
const b64=(u:Uint8Array)=>btoa(String.fromCharCode(...u));
const hex=(u:Uint8Array)=>Array.from(u).map(x=>x.toString(16).padStart(2,'0')).join('');
async function digest(text:string,alg:'SHA-256'|'SHA-1'='SHA-256'){return hex(new Uint8Array(await crypto.subtle.digest(alg,new TextEncoder().encode(text))))}
async function hashPassword(password:string,salt?:Uint8Array<ArrayBuffer>){const s=salt||crypto.getRandomValues(new Uint8Array(16));const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new Uint8Array(s),iterations:100000,hash:'SHA-256'},key,256);return `pbkdf2$100000$${b64(s)}$${b64(new Uint8Array(bits))}`}
async function verifyPassword(password:string,stored:string){const [,it,salt,hash]=stored.split('$');const s=Uint8Array.from(atob(salt),c=>c.charCodeAt(0));const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:s,iterations:Number(it),hash:'SHA-256'},key,256);return b64(new Uint8Array(bits))===hash}
async function sessionToken(){return b64(crypto.getRandomValues(new Uint8Array(32))).replace(/[^a-zA-Z0-9]/g,'')}
async function userFromReq(c:any){const h=c.req.header('Authorization')||'';if(!h.startsWith('Bearer '))return null;const token=h.slice(7);const th=await digest(token);return await c.env.DB.prepare("SELECT u.*,s.expires_at FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>? AND u.status='active'").bind(th,now()).first() as any}
async function staffFromReq(c:any){const u=await userFromReq(c);if(!u)return null;const s=await c.env.DB.prepare('SELECT st.*,r.name role FROM staff st JOIN roles r ON r.id=st.role_id WHERE st.user_id=? AND st.active=1').bind(u.id).first() as any;return s?{user:u,staff:s}:null}
async function requireStaff(c:any,permission?:string){const s=await staffFromReq(c);if(!s)return {error:'Unauthorized',status:401};if(s.staff.role==='super_admin')return s;if(permission){const p=await c.env.DB.prepare('SELECT 1 FROM role_permissions rp JOIN permissions p ON p.id=rp.permission_id WHERE rp.role_id=? AND p.name=?').bind(s.staff.role_id,permission).first();if(!p)return {error:'Forbidden',status:403}}return s}
async function log(c:any,staff:any,action:string,entity:string,id?:string,prev?:any,next?:any){await c.env.DB.prepare('INSERT INTO activity_logs(staff_user_id,action,entity,entity_id,previous_value,new_value,ip) VALUES(?,?,?,?,?,?,?)').bind(staff?.user?.id||null,action,entity,id||null,prev?JSON.stringify(prev):null,next?JSON.stringify(next):null,c.req.header('CF-Connecting-IP')||null).run()}
async function notifyAllCustomers(c:any,title:string,body:string){const users=(await c.env.DB.prepare("SELECT id FROM users WHERE status='active' AND NOT EXISTS(SELECT 1 FROM staff WHERE staff.user_id=users.id)").all()).results as any[];if(!users.length)return;const batch=users.map((u:any)=>c.env.DB.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(u.id,title,body));for(let i=0;i<batch.length;i+=50)await c.env.DB.batch(batch.slice(i,i+50));}
async function notifyStaff(c:any,title:string,body:string){const users=(await c.env.DB.prepare("SELECT u.id FROM users u JOIN staff st ON st.user_id=u.id WHERE u.status='active' AND st.active=1").all()).results as any[];if(!users.length)return;const batch=users.map((u:any)=>c.env.DB.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(u.id,title,body));for(let i=0;i<batch.length;i+=50)await c.env.DB.batch(batch.slice(i,i+50));}

app.use('*', async (c, next) => {
  const origin = c.req.header('Origin') || '';
  const allowedOrigins = [
    'https://shanoshanfragrance.netlify.app',
    'https://shanoshanfragrance.vercel.app',
    'https://shanoshanfragrance.infinityfreeapp.com',
    'https://shanoshanfragranceadmin.netlify.app',
    'https://shanoshanfragranceseller.vercel.app',
    ...(c.env.ALLOWED_ORIGINS || '')
      .split(',')
      .map((x: string) => x.trim())
      .filter(Boolean),
  ];

  if (c.req.method === 'OPTIONS') {
    if (origin && !allowedOrigins.includes(origin)) {
      return new Response(JSON.stringify({ error: 'Origin not allowed' }), {
        status: 403,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    return new Response(null, {
      status: 204,
      headers: {
        'Access-Control-Allow-Origin': origin,
        'Access-Control-Allow-Methods': 'GET,POST,PUT,PATCH,DELETE,OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type,Authorization,X-Cart-ID',
        'Access-Control-Allow-Credentials': 'true',
        'Access-Control-Max-Age': '86400',
        'Vary': 'Origin',
      },
    });
  }

  await next();

  if (origin && allowedOrigins.includes(origin)) {
    c.header('Access-Control-Allow-Origin', origin);
    c.header('Access-Control-Allow-Methods', 'GET,POST,PUT,PATCH,DELETE,OPTIONS');
    c.header('Access-Control-Allow-Headers', 'Content-Type,Authorization,X-Cart-ID');
    c.header('Access-Control-Allow-Credentials', 'true');
    c.header('Vary', 'Origin');
  }
});
app.get('/api/health',c=>json({ok:true,service:'SHANO SHAN API',time:now()}));

app.post('/api/auth/register',async c=>{const b=await c.req.json();const email=String(b.email||'').trim().toLowerCase(),name=String(b.name||'').trim(),password=String(b.password||'');if(!email||!name||password.length<8)return json({error:'Name, valid email and password of at least 8 characters are required'},400);if(await c.env.DB.prepare('SELECT id FROM users WHERE email=?').bind(email).first())return json({error:'Email already registered'},409);const ph=await hashPassword(password);const r=await c.env.DB.prepare('INSERT INTO users(email,password_hash,name,phone) VALUES(?,?,?,?)').bind(email,ph,name,String(b.phone||'')).run();const token=await sessionToken();await c.env.DB.prepare('INSERT INTO sessions(user_id,token_hash,expires_at) VALUES(?,?,?)').bind(r.meta.last_row_id,await digest(token),new Date(Date.now()+30*864e5).toISOString()).run();return json({user:{id:r.meta.last_row_id,email,name},token},201)});
app.post('/api/auth/login',async c=>{const b=await c.req.json();const email=String(b.email||'').trim().toLowerCase();const u=await c.env.DB.prepare('SELECT * FROM users WHERE email=?').bind(email).first() as any;if(!u||!(await verifyPassword(String(b.password||''),u.password_hash)))return json({error:'Invalid email or password'},401);const token=await sessionToken();await c.env.DB.prepare('INSERT INTO sessions(user_id,token_hash,expires_at) VALUES(?,?,?)').bind(u.id,await digest(token),new Date(Date.now()+30*864e5).toISOString()).run();return json({user:{id:u.id,email:u.email,name:u.name,phone:u.phone},token})});
app.get('/api/auth/me',async c=>{const u=await userFromReq(c);return u?json({user:{id:u.id,email:u.email,name:u.name,phone:u.phone}}):json({user:null},401)});
app.post('/api/auth/logout',async c=>{const h=c.req.header('Authorization')||'';if(h.startsWith('Bearer '))await c.env.DB.prepare('DELETE FROM sessions WHERE token_hash=?').bind(await digest(h.slice(7))).run();return json({ok:true})});

async function productDetail(c:any,p:any){const [images,variants,rating,views]=await Promise.all([c.env.DB.prepare('SELECT * FROM product_images WHERE product_id=? ORDER BY sort_order,id').bind(p.id).all(),c.env.DB.prepare('SELECT * FROM product_variants WHERE product_id=? AND active=1 ORDER BY id').bind(p.id).all(),c.env.DB.prepare("SELECT COUNT(*) review_count,COALESCE(AVG(rating),0) rating FROM reviews WHERE product_id=? AND status='approved'").bind(p.id).first(),c.env.DB.prepare('SELECT COUNT(*) total_views FROM product_views WHERE product_id=?').bind(p.id).first()]);return {...p,images:images.results,variants:variants.results,rating:Number((rating as any)?.rating||0),review_count:Number((rating as any)?.review_count||0),views:Number((views as any)?.total_views||0)}}
async function syncProductFromVariants(c:any,productId:number){const rows=(await c.env.DB.prepare('SELECT price,sale_price,stock FROM product_variants WHERE product_id=? AND active=1 ORDER BY id').bind(productId).all()).results as any[];if(!rows.length)return;const stock=rows.reduce((n:any,v:any)=>n+Number(v.stock||0),0);const price=Number(rows[0].price||0);const sale=rows.find(v=>v.sale_price!=null)?.sale_price??null;await c.env.DB.prepare('UPDATE products SET price=?,sale_price=?,stock=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(price,sale,stock,productId).run();}
app.get('/api/products',async c=>{const q=c.req.query('q')||'',cat=c.req.query('category'),gender=c.req.query('gender'),minRating=Number(c.req.query('min_rating')||0),size=c.req.query('size'),sort=c.req.query('sort')||'newest',page=Math.max(1,Number(c.req.query('page')||1)),limit=Math.min(48,Math.max(1,Number(c.req.query('limit')||12))),offset=(page-1)*limit;let where="WHERE p.active=1",params:any[]=[];if(q){where+=' AND (p.name LIKE ? OR p.sku LIKE ? OR p.tags LIKE ?)';params.push(`%${q}%`,`%${q}%`,`%${q}%`)}if(cat){where+=' AND (p.category_id=? OR c.slug=?)';params.push(Number(cat)||0,cat)}if(gender){where+=' AND p.gender=?';params.push(gender)}if(minRating>0)where+=" AND COALESCE((SELECT AVG(r.rating) FROM reviews r WHERE r.product_id=p.id AND r.status='approved'),0)>=?",params.push(minRating);if(size)where+=' AND EXISTS (SELECT 1 FROM product_variants sv WHERE sv.product_id=p.id AND sv.active=1 AND sv.name=?)',params.push(size);const count=await c.env.DB.prepare(`SELECT COUNT(*) n FROM products p LEFT JOIN categories c ON c.id=p.category_id ${where}`).bind(...params).first() as any;const order=sort==='price_asc'?'COALESCE(p.sale_price,p.price) ASC':sort==='price_desc'?'COALESCE(p.sale_price,p.price) DESC':sort==='rating'?'rating DESC, review_count DESC':sort==='views'?'views DESC':'p.id DESC';const rows=await c.env.DB.prepare(`SELECT p.*,c.name category_name,c.slug category_slug,(SELECT secure_url FROM product_images i WHERE i.product_id=p.id ORDER BY i.is_primary DESC,i.sort_order LIMIT 1) image_url,COALESCE((SELECT AVG(r.rating) FROM reviews r WHERE r.product_id=p.id AND r.status='approved'),0) rating,(SELECT COUNT(*) FROM reviews r WHERE r.product_id=p.id AND r.status='approved') review_count,(SELECT COUNT(*) FROM product_views v WHERE v.product_id=p.id) views,(SELECT GROUP_CONCAT(DISTINCT sv.name) FROM product_variants sv WHERE sv.product_id=p.id AND sv.active=1) sizes FROM products p LEFT JOIN categories c ON c.id=p.category_id ${where} ORDER BY ${order} LIMIT ? OFFSET ?`).bind(...params,limit,offset).all();return json({products:rows.results,page,limit,total:Number(count?.n||0)})});
app.get('/api/products/:slug',async c=>{const p=await c.env.DB.prepare('SELECT * FROM products WHERE slug=? AND active=1').bind(c.req.param('slug')).first();return p?json({product:await productDetail(c,p)}):json({error:'Product not found'},404)});
