app.get('/api/collections',async c=>json({collections:(await c.env.DB.prepare('SELECT * FROM collections WHERE active=1 ORDER BY sort_order,id').all()).results}));
app.get('/api/settings/site',async c=>{const rows=(await c.env.DB.prepare('SELECT key,value FROM settings').all()).results;const s:Object=Object.fromEntries(rows.map((r:any)=>[r.key,r.value]));const a=await c.env.DB.prepare("SELECT * FROM announcements WHERE enabled=1 AND (start_at IS NULL OR start_at<=?) AND (end_at IS NULL OR end_at>=?) ORDER BY priority DESC,sort_order,id LIMIT 10").bind(now(),now()).all();return json({settings:s,announcements:a.results})});
app.get('/api/homepage',async c=>json({banners:(await c.env.DB.prepare("SELECT * FROM banners WHERE active=1 AND (start_at IS NULL OR start_at<=?) AND (end_at IS NULL OR end_at>=?) ORDER BY sort_order,id").bind(now(),now()).all()).results,sections:(await c.env.DB.prepare("SELECT * FROM homepage_sections WHERE enabled=1 AND status='published' ORDER BY sort_order,id").all()).results}));

async function cart(c:any){const u=await userFromReq(c),guest=c.req.header('X-Cart-ID')||null;let row:any=u?await c.env.DB.prepare('SELECT * FROM carts WHERE user_id=?').bind(u.id).first():guest?await c.env.DB.prepare('SELECT * FROM carts WHERE guest_token=?').bind(guest).first():null;if(!row){if(u){const r=await c.env.DB.prepare('INSERT INTO carts(user_id) VALUES(?)').bind(u.id).run();row={id:r.meta.last_row_id,user_id:u.id}}else{const gt=guest||await sessionToken();const r=await c.env.DB.prepare('INSERT INTO carts(guest_token) VALUES(?)').bind(gt).run();row={id:r.meta.last_row_id,guest_token:gt}}}return {row,u,guest}}
app.get('/api/cart',async c=>{const {row}=await cart(c);const items=await c.env.DB.prepare('SELECT ci.*,p.name,p.slug,p.price,p.sale_price,p.stock,(SELECT secure_url FROM product_images i WHERE i.product_id=p.id ORDER BY i.is_primary DESC,i.sort_order LIMIT 1) image_url FROM cart_items ci JOIN products p ON p.id=ci.product_id WHERE ci.cart_id=?').bind(row.id).all();return json({cart:{...row,items:items.results}})});
app.post('/api/cart/items',async c=>{const b=await c.req.json(),qty=Math.max(1,Math.min(99,Number(b.quantity||1))),pid=Number(b.product_id),vid=b.variant_id?Number(b.variant_id):null;const {row}=await cart(c);const p:any=vid?await c.env.DB.prepare('SELECT * FROM product_variants WHERE id=? AND product_id=?').bind(vid,pid).first():await c.env.DB.prepare('SELECT * FROM products WHERE id=? AND active=1').bind(pid).first();if(!p)return json({error:'Product or variant unavailable'},404);const stock=Number(p.stock);const existing:any=await c.env.DB.prepare('SELECT quantity FROM cart_items WHERE cart_id=? AND product_id=? AND variant_id IS ?').bind(row.id,pid,vid).first();if((existing?.quantity||0)+qty>stock)return json({error:'Not enough stock'},400);if(existing)await c.env.DB.prepare('UPDATE cart_items SET quantity=quantity+? WHERE cart_id=? AND product_id=? AND variant_id IS ?').bind(qty,row.id,pid,vid).run();else await c.env.DB.prepare('INSERT INTO cart_items(cart_id,product_id,variant_id,quantity) VALUES(?,?,?,?)').bind(row.id,pid,vid,qty).run();return json({ok:true})});
app.patch('/api/cart/items/:id',async c=>{const b=await c.req.json(),qty=Math.max(1,Math.min(99,Number(b.quantity||1)));const {row}=await cart(c);const item:any=await c.env.DB.prepare('SELECT ci.*,COALESCE(v.stock,p.stock) stock FROM cart_items ci JOIN products p ON p.id=ci.product_id LEFT JOIN product_variants v ON v.id=ci.variant_id WHERE ci.id=? AND ci.cart_id=?').bind(Number(c.req.param('id')),row.id).first();if(!item||qty>item.stock)return json({error:'Invalid quantity'},400);await c.env.DB.prepare('UPDATE cart_items SET quantity=? WHERE id=? AND cart_id=?').bind(qty,item.id,row.id).run();return json({ok:true})});
app.delete('/api/cart/items/:id',async c=>{const {row}=await cart(c);await c.env.DB.prepare('DELETE FROM cart_items WHERE id=? AND cart_id=?').bind(Number(c.req.param('id')),row.id).run();return json({ok:true})});

app.post('/api/payment-receipts/preupload',async c=>{const u=await userFromReq(c);if(!u)return json({error:'Login required'},401);const fd=await c.req.formData(),file=fd.get('receipt');if(!(file instanceof File)||file.size>8*1024*1024)return json({error:'Please upload a receipt image/PDF up to 8MB'},400);const type=file.type||'';if(!(type.startsWith('image/')||type==='application/pdf'))return json({error:'Receipt must be an image or PDF'},400);const up=await cloudinaryUpload(c,file,`shano-shan/receipts/pending/${u.id}`);const token=crypto.randomUUID();await c.env.DB.prepare('INSERT INTO receipt_uploads(token,user_id,public_id,secure_url) VALUES(?,?,?,?)').bind(token,u.id,up.public_id,up.secure_url).run();return json({token,secure_url:up.secure_url},201)});

app.post('/api/orders',async c=>{const u=await userFromReq(c);if(!u)return json({error:'Please login to place your order'},401);const b=await c.req.json();if(!String(b.name||'')||!String(b.email||'')||!String(b.phone||'')||!String(b.address||'')||!String(b.city||'')||!String(b.province||''))return json({error:'Complete customer and shipping information is required, including province and city.'},400);const {row}=await cart(c);const items=(await c.env.DB.prepare('SELECT ci.*,p.name,p.sku,p.price,p.sale_price,p.stock active_stock,p.min_quantity,p.max_quantity,v.name variant_name,v.sku variant_sku,v.price variant_price,v.sale_price variant_sale_price,v.stock variant_stock,v.active variant_active FROM cart_items ci JOIN products p ON p.id=ci.product_id LEFT JOIN product_variants v ON v.id=ci.variant_id WHERE ci.cart_id=?').bind(row.id).all()).results as any[];if(!items.length)return json({error:'Cart is empty'},400);let subtotal=0;for(const i of items){if(!i.active_stock||i.quantity>Number(i.variant_id?i.variant_stock:i.active_stock))return json({error:`Insufficient stock for ${i.name}`},409);if(i.variant_id&&!i.variant_active)return json({error:`Selected size is no longer available for ${i.name}`},409);if(i.quantity<Number(i.min_quantity||1)||i.quantity>Number(i.max_quantity||99))return json({error:`Quantity limit exceeded for ${i.name}`},400);const price=Number(i.variant_id?(i.variant_sale_price??i.variant_price):(i.sale_price??i.price));subtotal+=price*Number(i.quantity)}const settings=Object.fromEntries((await c.env.DB.prepare('SELECT key,value FROM settings').all()).results.map((r:any)=>[r.key,r.value]));let method=String(b.payment_method||'cod');let paymentMethod:any=null;if(method.startsWith('pm_')){paymentMethod=await c.env.DB.prepare('SELECT * FROM payment_methods WHERE id=? AND active=1').bind(Number(method.slice(3))).first();if(!paymentMethod)return json({error:'Payment method is currently unavailable'},400);if(paymentMethod.method_type==='cod')method='cod'}if(method==='cod'&&settings.cod_enabled!=='1')return json({error:'COD is disabled'},400);if(method!=='cod'){if(!paymentMethod)return json({error:'Payment method is currently unavailable'},400);if(!String(b.receipt_token||''))return json({error:'Please upload receipt before placing your order'},400);const ru:any=await c.env.DB.prepare("SELECT * FROM receipt_uploads WHERE token=? AND user_id=? AND created_at>=datetime('now','-30 minutes')").bind(String(b.receipt_token),u.id).first();if(!ru)return json({error:'Receipt upload is missing or expired. Please upload the receipt again.'},400)}const quantity=items.reduce((n:any,i:any)=>n+Number(i.quantity),0);const fee=await deliveryFee(c,quantity,subtotal,method);const total=subtotal+fee;const seq:any=await c.env.DB.prepare('UPDATE order_sequence SET next_number=next_number+1 WHERE id=1 RETURNING prefix,next_number-1 AS issued').first();const orderNo=`${seq?.prefix||'SS-'}${Number(seq?.issued||Date.now())}`;const db=c.env.DB;const order=await db.prepare('INSERT INTO orders(order_number,user_id,name,email,phone,address,city,province,postal_code,country,subtotal,delivery_fee,total,payment_method,payment_status,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(orderNo,u?.id||null,String(b.name),String(b.email).toLowerCase(),String(b.phone),String(b.address),String(b.city),String(b.province),String(b.postal_code||''),'Pakistan',subtotal,fee,total,method,method==='cod'?'Pending':'Submitted',method==='cod'?'Pending':'Payment Verification').run();await db.prepare("INSERT INTO tracking_events(order_id,status,title,description) VALUES(?,?,?,?)").bind(order.meta.last_row_id,method==='cod'?'Pending':'Payment Verification',method==='cod'?'Order received':'Payment submitted','Your order has been received by SHANO SHAN.').run();for(const i of items){const price=Number(i.variant_id?(i.variant_sale_price??i.variant_price):(i.sale_price??i.price));await db.prepare('INSERT INTO order_items(order_id,product_id,variant_id,name,sku,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?,?,?)').bind(order.meta.last_row_id,i.product_id,i.variant_id,i.name,i.variant_id?i.variant_name:i.name,i.quantity,price,price*i.quantity).run();if(i.variant_id) await db.prepare('UPDATE product_variants SET stock=stock-? WHERE id=? AND stock>=?').bind(i.quantity,i.variant_id,i.quantity).run(); else await db.prepare('UPDATE products SET stock=stock-?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND stock>=?').bind(i.quantity,i.product_id,i.quantity).run();}const payment=await db.prepare('INSERT INTO payments(order_id,method,amount,status) VALUES(?,?,?,?)').bind(order.meta.last_row_id,method,total,method==='cod'?'Pending':'Submitted').run();if(method!=='cod'){const ru:any=await db.prepare('SELECT * FROM receipt_uploads WHERE token=? AND user_id=?').bind(String(b.receipt_token),u.id).first();if(!ru)return json({error:'Receipt upload is missing'},400);await db.prepare('INSERT INTO payment_receipts(payment_id,public_id,secure_url) VALUES(?,?,?)').bind(payment.meta.last_row_id,ru.public_id,ru.secure_url).run();await db.prepare('DELETE FROM receipt_uploads WHERE id=?').bind(ru.id).run()}await db.prepare('DELETE FROM cart_items WHERE cart_id=?').bind(row.id).run();if(u)await db.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(u.id,'Order placed',`Your order ${orderNo} has been placed.`).run();await notifyStaff(c,'New order received',`New ${method==='cod'?'COD':'advance payment'} order ${orderNo} from ${String(b.name)} — PKR ${total.toLocaleString()}.`);return json({order_number:orderNo,total,status:method==='cod'?'Pending':'Payment Verification'},201)});
app.get('/api/notifications',async c=>{const u=await userFromReq(c);if(!u)return json({notifications:[],unread:0},401);const rows=(await c.env.DB.prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 50').bind(u.id).all()).results;const unread=await c.env.DB.prepare('SELECT COUNT(*) n FROM notifications WHERE user_id=? AND read_at IS NULL').bind(u.id).first() as any;return json({notifications:rows,unread:Number(unread?.n||0)})});
app.get('/api/admin/notifications',async c=>{const a=await requireStaff(c);if('error'in a)return json({error:a.error},a.status);const rows=(await c.env.DB.prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 50').bind(a.user.id).all()).results;const unread=await c.env.DB.prepare('SELECT COUNT(*) n FROM notifications WHERE user_id=? AND read_at IS NULL').bind(a.user.id).first() as any;return json({notifications:rows,unread:Number(unread?.n||0)})});
app.patch('/api/admin/notifications/:id/read',async c=>{const a=await requireStaff(c);if('error'in a)return json({error:a.error},a.status);await c.env.DB.prepare('UPDATE notifications SET read_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?').bind(Number(c.req.param('id')),a.user.id).run();return json({ok:true})});
app.patch('/api/notifications/:id/read',async c=>{const u=await userFromReq(c);if(!u)return json({error:'Login required'},401);await c.env.DB.prepare('UPDATE notifications SET read_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?').bind(Number(c.req.param('id')),u.id).run();return json({ok:true})});
app.get('/api/orders/:id',async c=>{const u=await userFromReq(c);if(!u)return json({error:'Login required'},401);const id=c.req.param('id');const o:any=await c.env.DB.prepare('SELECT * FROM orders WHERE (id=? OR order_number=?) AND user_id=?').bind(Number(id)||0,id,u.id).first();if(!o)return json({error:'Order not found'},404);const [items,tracking]=await Promise.all([c.env.DB.prepare('SELECT oi.*,v.name variant_name FROM order_items oi LEFT JOIN product_variants v ON v.id=oi.variant_id WHERE oi.order_id=?').bind(o.id).all(),c.env.DB.prepare('SELECT * FROM tracking_events WHERE order_id=? ORDER BY id ASC').bind(o.id).all()]);const payment:any=await c.env.DB.prepare('SELECT p.*,r.secure_url receipt_url FROM payments p LEFT JOIN payment_receipts r ON r.payment_id=p.id WHERE p.order_id=?').bind(o.id).first();return json({order:o,items:items.results,payment,tracking:tracking.results})});
async function cloudinaryUpload(c:any,file:File,folder:string){const timestamp=Math.floor(Date.now()/1000);const signature=await digest(`folder=${folder}&timestamp=${timestamp}${c.env.CLOUDINARY_API_SECRET}`,'SHA-1');const fd=new FormData();fd.append('file',file);fd.append('api_key',c.env.CLOUDINARY_API_KEY);fd.append('timestamp',String(timestamp));fd.append('folder',folder);fd.append('signature',signature);const r=await fetch(`https://api.cloudinary.com/v1_1/${c.env.CLOUDINARY_CLOUD_NAME}/auto/upload`,{method:'POST',body:fd});if(!r.ok)throw new Error('Cloudinary upload failed');return await r.json() as any}
app.post('/api/orders/:id/receipt',async c=>{const u=await userFromReq(c);if(!u)return json({error:'Login required'},401);const o:any=await c.env.DB.prepare('SELECT * FROM orders WHERE id=? AND user_id=?').bind(Number(c.req.param('id')),u.id).first();if(!o)return json({error:'Order not found'},404);const payment:any=await c.env.DB.prepare('SELECT * FROM payments WHERE order_id=?').bind(o.id).first();if(!payment||payment.method==='cod')return json({error:'Receipt upload is not available for this payment method'},400);const fd=await c.req.formData(),file=fd.get('receipt');if(!(file instanceof File)||file.size>8*1024*1024)return json({error:'Receipt image/file is required and must be <=8MB'},400);const up=await cloudinaryUpload(c,file,`shano-shan/receipts/${o.order_number}`);await c.env.DB.prepare('INSERT INTO payment_receipts(payment_id,public_id,secure_url) VALUES(?,?,?) ON CONFLICT(payment_id) DO UPDATE SET public_id=excluded.public_id,secure_url=excluded.secure_url,submitted_at=CURRENT_TIMESTAMP').bind(payment.id,up.public_id,up.secure_url).run();await c.env.DB.prepare("UPDATE payments SET status='Submitted',reference=?,note=? WHERE id=?").bind(String(fd.get('reference')||''),String(fd.get('note')||''),payment.id).run();await c.env.DB.prepare("UPDATE orders SET payment_status='Submitted',status='Payment Verification',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(o.id).run();return json({ok:true})});

app.post('/api/reviews',async c=>{const u=await userFromReq(c);if(!u)return json({error:'Login required'},401);const b=await c.req.json();const p=await c.env.DB.prepare('SELECT id FROM products WHERE id=? AND active=1').bind(Number(b.product_id)).first();if(!p)return json({error:'Product not found'},404);const rating=Number(b.rating);if(rating<1||rating>5)return json({error:'Rating must be between 1 and 5'},400);const purchased=await c.env.DB.prepare("SELECT o.delivered_at FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.product_id=? AND o.user_id=? AND o.status='Delivered' AND o.delivered_at IS NOT NULL AND o.delivered_at>=datetime('now','-7 day') ORDER BY o.delivered_at DESC LIMIT 1").bind(Number(b.product_id),u.id).first();if(!purchased)return json({error:'Reviews are available only to the customer who received the product, within 7 days of delivery.'},403);try{await c.env.DB.prepare('INSERT INTO reviews(product_id,user_id,rating,body,verified_purchase,status) VALUES(?,?,?,?,?,?)').bind(Number(b.product_id),u.id,rating,String(b.body||''),1,'pending').run()}catch{return json({error:'You have already reviewed this product'},409)}return json({ok:true},201)});

app.post('/api/admin/setup',async c=>{if(c.req.header('X-Admin-Setup-Key')!==c.env.ADMIN_SETUP_KEY)return json({error:'Invalid setup key'},403);const b=await c.req.json();if(String(b.password||'').length<12)return json({error:'Use a password of at least 12 characters'},400);const exists=await c.env.DB.prepare('SELECT 1 FROM staff LIMIT 1').first();if(exists)return json({error:'Admin already initialized'},409);const email=String(b.email||'').trim().toLowerCase(),name=String(b.name||'Owner').trim();const ph=await hashPassword(String(b.password));const u=await c.env.DB.prepare('INSERT INTO users(email,password_hash,name) VALUES(?,?,?)').bind(email,ph,name).run();const role:any=await c.env.DB.prepare("SELECT id FROM roles WHERE name='super_admin'").first();await c.env.DB.prepare('INSERT INTO staff(user_id,role_id) VALUES(?,?)').bind(u.meta.last_row_id,role.id).run();const perms=(await c.env.DB.prepare('SELECT id FROM permissions').all()).results;for(const p of perms as any[])await c.env.DB.prepare('INSERT OR IGNORE INTO role_permissions(role_id,permission_id) VALUES(?,?)').bind(role.id,p.id).run();return json({ok:true,message:'Initial admin created. You can now log in.'},201)});

app.post('/api/ai/chat',async c=>{
  const body=await c.req.json().catch(()=>({}));
  const message=String(body.message||'').trim().slice(0,2500);
  const mode=body.mode==='admin'?'admin':'customer';
  if(!message)return json({error:'Message is required'},400);

  if(mode==='admin'){
    const auth=await requireStaff(c);
    if('error'in auth)return json({error:auth.error},auth.status);
  }

  let aiSystem='';
  let aiContext='';
  try{
    const products=(await c.env.DB.prepare(`
      SELECT p.id,p.name,p.slug,p.category_id,p.gender,p.description,p.short_description,p.tags,
      p.top_notes,p.heart_notes,p.base_notes,p.price,p.sale_price,p.stock,p.min_quantity,p.max_quantity,
      (SELECT GROUP_CONCAT(v.name||' @ PKR '||COALESCE(v.sale_price,v.price)||' / stock '||v.stock)
       FROM product_variants v WHERE v.product_id=p.id AND v.active=1) variants
      FROM products p WHERE p.active=1 ORDER BY p.id DESC LIMIT 60
    `).all()).results as any[];

    const settingsRows=(await c.env.DB.prepare(`
      SELECT key,value FROM settings WHERE key IN (
        'contact_phone','contact_email','contact_whatsapp','instagram','facebook','tiktok','youtube',
        'website','footer_text','shipping_policy','return_policy','privacy_policy','terms',
        'about_story','founder_name','founder_bio','founder_quote','delivery_fee','free_shipping_threshold'
      )
    `).all()).results as any[];
    const settings=Object.fromEntries(settingsRows.map((r:any)=>[r.key,r.value]));

    const methods=(await c.env.DB.prepare(`
      SELECT name,instructions FROM payment_methods WHERE active=1 ORDER BY display_order,id
    `).all()).results as any[];

    const rules=(await c.env.DB.prepare(`
      SELECT min_qty,max_qty,fee FROM delivery_rules WHERE active=1 ORDER BY min_qty
    `).all()).results as any[];

    const catalog=products.map((p:any)=>({
      name:p.name,gender:p.gender,description:p.short_description||p.description||'',
      tags:p.tags||'',top_notes:p.top_notes||'',heart_notes:p.heart_notes||'',base_notes:p.base_notes||'',
      price:p.sale_price??p.price,stock:p.stock,minimum:p.min_quantity||1,maximum:p.max_quantity||99,
      variants:p.variants||''
    }));

    const system=aiSystem=`
You are SHANO AI, the official multilingual customer/seller assistant for SHANO SHAN FRAGRANCE.
You are NOT the Find Your Scent quiz. You are a separate conversational store agent.

Scope:
- Answer perfume, attar, fragrance, notes, concentration, sizes/ML, prices, stock, variants, product comparisons, delivery, payment methods, returns/policies, contact information, website navigation, and other SHANO SHAN store questions.
- For admin mode, also help with seller operations such as banners, Live Top Bar, products, variants, stock, content, delivery rules and payment setup. Never expose secrets, tokens, passwords, Cloudinary credentials, database internals or private customer information.
- Use ONLY the supplied live store data for specific prices, stock, variants, payment methods, contact details and policies. Never invent a product, price, stock level, discount, review, delivery fee or policy.
- If the store data does not contain the answer, say clearly that the information is not available and suggest contacting SHANO SHAN.
- If asked something unrelated to perfumes/store operations, politely say you are the SHANO SHAN store assistant and redirect to store-related help.
- Reply in the SAME language/script as the customer's message. Support English, Urdu, Roman Urdu, Arabic, Punjabi, Hindi, Bengali and other languages as well as practical multilingual conversations. If the customer mixes languages, answer naturally in the same mix.
- Keep answers helpful and concise, but explain perfume terminology when useful.
- Never claim to have placed/cancelled an order or changed account data unless an actual API action exists.
`;

    const context=aiContext=JSON.stringify({
      store:{
        brand:"SHANO SHAN FRAGRANCE",
        contact:{phone:settings.contact_phone,email:settings.contact_email,whatsapp:settings.contact_whatsapp},
        social:{instagram:settings.instagram,facebook:settings.facebook,tiktok:settings.tiktok,youtube:settings.youtube,website:settings.website},
        policies:{shipping:settings.shipping_policy,returns:settings.return_policy,privacy:settings.privacy_policy,terms:settings.terms},
        founder:{name:settings.founder_name,bio:settings.founder_bio,quote:settings.founder_quote},
        payment_methods:methods,
        delivery_rules:rules,
        default_delivery_fee:settings.delivery_fee,
        free_shipping_threshold:settings.free_shipping_threshold
      },
      catalog
    });

    const messages=[
      {role:'system',content:aiSystem},
      {role:'system',content:`LIVE SHANO SHAN STORE DATA:\n${aiContext}`},
      {role:'user',content:message}
    ];

    // Prefer the currently active multilingual 3B model. Keep the fast 3.1 model
    // as a second path so a temporary model capacity/availability issue does not
    // immediately surface as an unavailable assistant to customers.
    const models=['@cf/meta/llama-3.2-3b-instruct','@cf/meta/llama-3.1-8b-instruct-fp8-fast','@cf/meta/llama-3.3-70b-instruct-fp8-fast'];
    let lastError:any=null;
    for(const model of models){
      try{
        const result:any=await c.env.AI.run(model,{messages,max_tokens:700,temperature:0.25});
        const reply=String(result?.response||result?.result?.response||'').trim();
        if(reply)return json({reply});
      }catch(error){
        lastError=error;
        console.error(`AI model error (${model})`,error);
      }
    }
    if(lastError)console.error('All SHANO AI models failed',lastError);
    return json({error:'AI service is temporarily busy. Please try again in a moment.'},503);
  }catch(e){
    console.error('AI request preparation error',e);
    return json({error:'AI service is temporarily busy. Please try again in a moment.'},503);
  }
});

app.get('/api/admin/dashboard',async c=>{const a=await requireStaff(c,'analytics');if('error'in a)return json({error:a.error},a.status);const q=async(sql:string)=>await c.env.DB.prepare(sql).first() as any;const excluded="status NOT IN ('Cancelled','Refunded')";return json({sales:{today:(await q(`SELECT COALESCE(SUM(subtotal-discount),0) n FROM orders WHERE date(created_at,'+5 hours')=date('now','+5 hours') AND ${excluded}`)).n,month:(await q(`SELECT COALESCE(SUM(subtotal-discount),0) n FROM orders WHERE strftime('%Y-%m',created_at,'+5 hours')=strftime('%Y-%m','now','+5 hours') AND ${excluded}`)).n,total:(await q(`SELECT COALESCE(SUM(subtotal-discount),0) n FROM orders WHERE ${excluded}`)).n,delivery_today:(await q(`SELECT COALESCE(SUM(delivery_fee),0) n FROM orders WHERE date(created_at,'+5 hours')=date('now','+5 hours') AND ${excluded}`)).n,delivery_month:(await q(`SELECT COALESCE(SUM(delivery_fee),0) n FROM orders WHERE strftime('%Y-%m',created_at,'+5 hours')=strftime('%Y-%m','now','+5 hours') AND ${excluded}`)).n,delivery_total:(await q(`SELECT COALESCE(SUM(delivery_fee),0) n FROM orders WHERE ${excluded}`)).n},orders:{pending:(await q("SELECT COUNT(*) n FROM orders WHERE status='Pending'")).n,payment:(await q("SELECT COUNT(*) n FROM orders WHERE status='Payment Verification'")).n,processing:(await q("SELECT COUNT(*) n FROM orders WHERE status IN ('Confirmed','Processing','Packed')")).n,shipped:(await q("SELECT COUNT(*) n FROM orders WHERE status IN ('Shipped','Out for Delivery')")).n,delivered:(await q("SELECT COUNT(*) n FROM orders WHERE status='Delivered'")).n},products:{total:(await q('SELECT COUNT(*) n FROM products')).n,active:(await q('SELECT COUNT(*) n FROM products WHERE active=1')).n,low:(await q('SELECT COUNT(*) n FROM products WHERE active=1 AND stock>0 AND stock<=low_stock_threshold')).n,out:(await q('SELECT COUNT(*) n FROM products WHERE active=1 AND stock=0')).n},customers:{total:(await q('SELECT COUNT(*) n FROM users WHERE NOT EXISTS(SELECT 1 FROM staff WHERE staff.user_id=users.id)')).n}})});
app.get('/api/admin/products',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);return json({products:(await c.env.DB.prepare('SELECT * FROM products ORDER BY id DESC').all()).results})});
app.post('/api/admin/products',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);const b=await c.req.json();if(!b.name||!b.slug||Number.isNaN(Number(b.price)))return json({error:'Name, slug and price required'},400);try{const r=await c.env.DB.prepare(`INSERT INTO products(name,slug,sku,category_id,collection_id,gender,short_description,description,price,sale_price,stock,low_stock_threshold,weight,fragrance_family,top_notes,heart_notes,base_notes,longevity,sillage,ingredients,tags,badges,featured,best_seller,new_arrival,limited_edition,active,seo_title,seo_description,seo_keywords,min_quantity,max_quantity) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(b.name,b.slug,b.sku||null,b.category_id||null,b.collection_id||null,b.gender||null,b.short_description||null,b.description||null,Number(b.price),b.sale_price===''?null:(b.sale_price??null),Number(b.stock||0),Number(b.low_stock_threshold||3),b.weight||null,b.fragrance_family||null,b.top_notes||null,b.heart_notes||null,b.base_notes||null,b.longevity||null,b.sillage||null,b.ingredients||null,b.tags||null,b.badges||null,Number(!!b.featured),Number(!!b.best_seller),Number(!!b.new_arrival),Number(!!b.limited_edition),b.active===false?0:1,b.seo_title||null,b.seo_description||null,b.seo_keywords||null,Math.max(1,Number(b.min_quantity||1)),Math.max(1,Number(b.max_quantity||99))).run();await log(c,a,'create','product',String(r.meta.last_row_id),null,b);await notifyAllCustomers(c,'New fragrance added',`${String(b.name)} is now available at SHANO SHAN.`);return json({id:r.meta.last_row_id},201)}catch(e){return json({error:'Could not create product; check slug/SKU uniqueness'},400)}});
app.put('/api/admin/products/:id',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id')),b=await c.req.json(),old=await c.env.DB.prepare('SELECT * FROM products WHERE id=?').bind(id).first();if(!old)return json({error:'Not found'},404);const allowed=['name','slug','sku','category_id','collection_id','gender','short_description','description','price','sale_price','stock','low_stock_threshold','weight','fragrance_family','top_notes','heart_notes','base_notes','longevity','sillage','ingredients','tags','badges','featured','best_seller','new_arrival','limited_edition','active','seo_title','seo_description','seo_keywords','min_quantity','max_quantity'];const sets:string[]=[];const vals:any[]=[];for(const k of allowed)if(k in b){sets.push(`${k}=?`);vals.push(b[k]===''?null:b[k])}if(!sets.length)return json({ok:true});sets.push('updated_at=CURRENT_TIMESTAMP');await c.env.DB.prepare(`UPDATE products SET ${sets.join(',')} WHERE id=?`).bind(...vals,id).run();await log(c,a,'update','product',String(id),old,b);const oldPrice=Number((old as any).price||0),oldSale=(old as any).sale_price==null?null:Number((old as any).sale_price);const newPrice='price' in b?Number(b.price):oldPrice,newSale='sale_price' in b?(b.sale_price===''||b.sale_price==null?null:Number(b.sale_price)):oldSale;if(newPrice>oldPrice || (newSale!=null&&oldSale!=null&&newSale>oldSale)){await notifyAllCustomers(c,'Price updated',`${String((old as any).name)} price has been updated. Check the latest price on SHANO SHAN.`)}return json({ok:true})});
app.get('/api/admin/products/:id/images',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);return json({images:(await c.env.DB.prepare('SELECT * FROM product_images WHERE product_id=? ORDER BY sort_order,id').bind(Number(c.req.param('id'))).all()).results})});
app.patch('/api/admin/products/:id/images/:imageId',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);const pid=Number(c.req.param('id')),iid=Number(c.req.param('imageId')),b=await c.req.json();const img=await c.env.DB.prepare('SELECT * FROM product_images WHERE id=? AND product_id=?').bind(iid,pid).first();if(!img)return json({error:'Image not found'},404);if(b.action==='primary'){await c.env.DB.prepare('UPDATE product_images SET is_primary=0 WHERE product_id=?').bind(pid).run();await c.env.DB.prepare('UPDATE product_images SET is_primary=1,sort_order=0 WHERE id=?').bind(iid).run()}else if(b.action==='order'){const rows:any[]=(await c.env.DB.prepare('SELECT id,sort_order FROM product_images WHERE product_id=? ORDER BY sort_order,id').bind(pid).all()).results as any[];const from=rows.findIndex(x=>Number(x.id)===iid);const to=Math.max(0,Math.min(rows.length-1,Number(b.sort_order)));if(from<0)return json({error:'Image not found'},404);if(from!==to){const other=rows[to];await c.env.DB.prepare('UPDATE product_images SET sort_order=? WHERE id=?').bind(Number(other.sort_order),iid).run();await c.env.DB.prepare('UPDATE product_images SET sort_order=? WHERE id=?').bind(Number(rows[from].sort_order),other.id).run()}}else return json({error:'Invalid image action'},400);return json({ok:true})});
app.delete('/api/admin/products/:id/images/:imageId',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);const pid=Number(c.req.param('id')),iid=Number(c.req.param('imageId'));const img:any=await c.env.DB.prepare('SELECT * FROM product_images WHERE id=? AND product_id=?').bind(iid,pid).first();if(!img)return json({error:'Image not found'},404);await c.env.DB.prepare('DELETE FROM product_images WHERE id=? AND product_id=?').bind(iid,pid).run();if(Number(img.is_primary)){const next:any=await c.env.DB.prepare('SELECT id FROM product_images WHERE product_id=? ORDER BY sort_order,id LIMIT 1').bind(pid).first();if(next)await c.env.DB.prepare('UPDATE product_images SET is_primary=1 WHERE id=?').bind(next.id).run()}return json({ok:true})});
app.post('/api/admin/products/:id/images',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id')),p=await c.env.DB.prepare('SELECT id FROM products WHERE id=?').bind(id).first();if(!p)return json({error:'Not found'},404);const fd=await c.req.formData(),files=fd.getAll('files');const results=[];for(const f of files){if(!(f instanceof File)||f.size>10*1024*1024)continue;const up=await cloudinaryUpload(c,f,`shano-shan/products/${id}`);const r=await c.env.DB.prepare('INSERT INTO product_images(product_id,public_id,secure_url,width,height,format,is_primary,sort_order) VALUES(?,?,?,?,?,?,?,?)').bind(id,up.public_id,up.secure_url,up.width||null,up.height||null,up.format||null,0,Date.now()%1000000).run();await c.env.DB.prepare('INSERT OR IGNORE INTO media(public_id,secure_url,width,height,format) VALUES(?,?,?,?,?)').bind(up.public_id,up.secure_url,up.width||null,up.height||null,up.format||null).run();results.push({id:r.meta.last_row_id,url:up.secure_url})}return json({images:results})});
app.post('/api/orders/:id/action',async c=>{const u=await userFromReq(c);if(!u)return json({error:'Login required'},401);const id=Number(c.req.param('id')),b=await c.req.json(),action=String(b.action||'');if(!['cancel','return'].includes(action))return json({error:'Invalid request'},400);const o:any=await c.env.DB.prepare('SELECT * FROM orders WHERE id=? AND user_id=?').bind(id,u.id).first();if(!o)return json({error:'Order not found'},404);const blocked=['Shipped','Out for Delivery'];if(blocked.includes(o.status))return json({error:'Cancellation or return is not available while the order is shipping.'},400);if(action==='return'&&o.status!=='Delivered')return json({error:'Return becomes available after delivery.'},400);if(action==='cancel'&&['Cancelled','Returned','Refunded'].includes(o.status))return json({error:'This order is already closed.'},400);if(o.customer_action_status==='requested')return json({error:'Your request is already waiting for admin confirmation.'},409);await c.env.DB.prepare('UPDATE orders SET customer_action=?,customer_action_reason=?,customer_action_status=\'requested\',refund_status=\'requested\',updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(action,String(b.reason||''),id).run();await c.env.DB.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(u.id,action==='return'?'Return request submitted':'Cancellation request submitted',`Your ${action} request for ${o.order_number} is waiting for SHANO SHAN admin confirmation.`).run();return json({ok:true})});
app.post('/api/orders/:id/refund-details',async c=>{const u=await userFromReq(c);if(!u)return json({error:'Login required'},401);const id=Number(c.req.param('id')),b=await c.req.json(),o:any=await c.env.DB.prepare('SELECT * FROM orders WHERE id=? AND user_id=?').bind(id,u.id).first();if(!o)return json({error:'Order not found'},404);if(!['approved','awaiting_details','details_requested'].includes(o.refund_status))return json({error:'Refund details are not requested for this order yet.'},400);if(!String(b.refund_account_title||'').trim()||!String(b.refund_account_number||'').trim()||!String(b.refund_method||'').trim())return json({error:'Refund method, account title and account number are required.'},400);await c.env.DB.prepare('UPDATE orders SET refund_status=\'details_submitted\',refund_account_title=?,refund_account_number=?,refund_bank_name=?,refund_iban=?,refund_phone=?,refund_method=?,refund_note=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(String(b.refund_account_title),String(b.refund_account_number),String(b.refund_bank_name||''),String(b.refund_iban||''),String(b.refund_phone||''),String(b.refund_method),String(b.refund_note||''),id).run();await c.env.DB.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(u.id,'Refund details received','Your refund details are ready for admin processing.').run();return json({ok:true})});
app.patch('/api/admin/orders/:id/customer-action',async c=>{const a=await requireStaff(c,'orders');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id')),b=await c.req.json(),decision=String(b.decision||'');if(!['approve','reject'].includes(decision))return json({error:'Invalid decision'},400);const o:any=await c.env.DB.prepare('SELECT * FROM orders WHERE id=?').bind(id).first();if(!o||o.customer_action_status!=='requested')return json({error:'No pending customer request'},404);if(decision==='reject'){await c.env.DB.prepare("UPDATE orders SET customer_action_status='none',refund_status='not_requested',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(id).run();if(o.user_id)await c.env.DB.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(o.user_id,'Request declined',`Your ${o.customer_action||'order'} request for ${o.order_number} was declined.`).run();return json({ok:true})}const finalStatus=o.customer_action==='return'?'Returned':'Cancelled';const items=(await c.env.DB.prepare('SELECT product_id,variant_id,quantity FROM order_items WHERE order_id=?').bind(id).all()).results as any[];const stockOps=items.map((i:any)=>i.variant_id?c.env.DB.prepare('UPDATE product_variants SET stock=stock+? WHERE id=?').bind(Number(i.quantity),Number(i.variant_id)):c.env.DB.prepare('UPDATE products SET stock=stock+?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(Number(i.quantity),Number(i.product_id)));await c.env.DB.batch(stockOps);await c.env.DB.prepare("UPDATE orders SET status=?,customer_action_status='approved',refund_status='awaiting_details',refund_amount=total,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(finalStatus,id).run();if(o.user_id)await c.env.DB.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(o.user_id,'Refund ready','Your request has been approved. Your refund is ready for processing. Please add your refund account details.').run();await log(c,a,'approve_customer_action','order',String(id),o,{status:finalStatus});return json({ok:true})});
app.post('/api/admin/orders/:id/refund',async c=>{const a=await requireStaff(c,'payments');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id')),o:any=await c.env.DB.prepare('SELECT * FROM orders WHERE id=?').bind(id).first();if(!o)return json({error:'Order not found'},404);if(o.refund_status!=='details_submitted')return json({error:'Customer refund details have not been submitted.'},400);const fd=await c.req.formData(),file=fd.get('receipt');if(!(file instanceof File))return json({error:'Refund payment receipt is required.'},400);if(file.size>8*1024*1024)return json({error:'Refund receipt must be <=8MB'},400);const up=await cloudinaryUpload(c,file,`shano-shan/refunds/${o.order_number}`);await c.env.DB.prepare("UPDATE orders SET refund_status='refunded',payment_status='Refunded',refund_receipt_public_id=?,refund_receipt_url=?,refund_approved_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(up.public_id,up.secure_url,id).run();if(o.user_id)await c.env.DB.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(o.user_id,'Refund completed',`Your refund for ${o.order_number} has been processed. The refund payment receipt is available in your order details.`).run();await log(c,a,'refund_order','order',String(id),o,{refund_status:'refunded'});return json({ok:true,receipt_url:up.secure_url})});
app.get('/api/admin/orders',async c=>{const a=await requireStaff(c,'orders');if('error'in a)return json({error:a.error},a.status);const q=c.req.query('q')||'',status=c.req.query('status')||'',paymentStatus=c.req.query('payment_status')||'',from=c.req.query('from')||'',to=c.req.query('to')||'',sort=c.req.query('sort')||'newest';let sql='SELECT * FROM orders WHERE 1=1',p:any[]=[];if(q){sql+=' AND (order_number LIKE ? OR name LIKE ? OR phone LIKE ? OR email LIKE ?)';const x=`%${q}%`;p.push(x,x,x,x)}if(status){sql+=' AND status=?';p.push(status)}if(paymentStatus){sql+=' AND payment_status=?';p.push(paymentStatus)}if(from){sql+=' AND date(created_at)>=date(?)';p.push(from)}if(to){sql+=' AND date(created_at)<=date(?)';p.push(to)}sql+=sort==='oldest'?' ORDER BY id ASC':sort==='highest'?' ORDER BY total DESC, id DESC':sort==='lowest'?' ORDER BY total ASC, id DESC':' ORDER BY id DESC';sql+=' LIMIT 500';return json({orders:(await c.env.DB.prepare(sql).bind(...p).all()).results})});
app.get('/api/admin/orders/:id',async c=>{const a=await requireStaff(c,'orders');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id'));const o=await c.env.DB.prepare('SELECT * FROM orders WHERE id=?').bind(id).first();if(!o)return json({error:'Not found'},404);const [items,payment,tracking]=await Promise.all([c.env.DB.prepare('SELECT oi.*,v.name variant_name FROM order_items oi LEFT JOIN product_variants v ON v.id=oi.variant_id WHERE oi.order_id=?').bind(id).all(),c.env.DB.prepare('SELECT p.*,r.secure_url receipt_url,r.public_id receipt_public_id FROM payments p LEFT JOIN payment_receipts r ON r.payment_id=p.id WHERE p.order_id=?').bind(id).first(),c.env.DB.prepare('SELECT * FROM tracking_events WHERE order_id=? ORDER BY id ASC').bind(id).all()]);return json({order:o,items:items.results,payment,tracking:tracking.results})});
app.delete('/api/admin/orders/:id',async c=>{const a=await requireStaff(c,'orders');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id'));const o:any=await c.env.DB.prepare('SELECT * FROM orders WHERE id=?').bind(id).first();if(!o)return json({error:'Order not found'},404);const items=(await c.env.DB.prepare('SELECT product_id,variant_id,quantity FROM order_items WHERE order_id=?').bind(id).all()).results as any[];const statements:any[]=[];for(const i of items){if(i.variant_id)statements.push(c.env.DB.prepare('UPDATE product_variants SET stock=stock+? WHERE id=?').bind(Number(i.quantity),Number(i.variant_id)));else statements.push(c.env.DB.prepare('UPDATE products SET stock=stock+?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(Number(i.quantity),Number(i.product_id)))}const payments=(await c.env.DB.prepare('SELECT id FROM payments WHERE order_id=?').bind(id).all()).results as any[];for(const pay of payments)statements.push(c.env.DB.prepare('DELETE FROM payment_receipts WHERE payment_id=?').bind(pay.id));statements.push(c.env.DB.prepare('DELETE FROM payments WHERE order_id=?').bind(id));statements.push(c.env.DB.prepare('DELETE FROM order_items WHERE order_id=?').bind(id));statements.push(c.env.DB.prepare('DELETE FROM orders WHERE id=?').bind(id));await c.env.DB.batch(statements);await log(c,a,'delete','order',String(id),o,null);return json({ok:true})});
app.patch('/api/admin/orders/:id/status',async c=>{const a=await requireStaff(c,'orders');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id')),b=await c.req.json(),allowed=['Pending','Payment Verification','Confirmed','Processing','Packed','Shipped','Out for Delivery','Delivered','Cancelled','Returned','Refunded'];if(!allowed.includes(b.status))return json({error:'Invalid status'},400);const old:any=await c.env.DB.prepare('SELECT * FROM orders WHERE id=?').bind(id).first();if(!old)return json({error:'Order not found'},404);const deliveredAt=b.status==='Delivered'?(old.delivered_at||now()):old.delivered_at;await c.env.DB.prepare('UPDATE orders SET status=?,tracking_number=?,courier=?,tracking_url=?,internal_notes=?,delivered_at=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(b.status,b.tracking_number||null,b.courier||null,b.tracking_url||null,b.internal_notes||null,deliveredAt,id).run();await c.env.DB.prepare("INSERT INTO tracking_events(order_id,status,title,description) VALUES(?,?,?,?)").bind(id,b.status,({Pending:'Order received','Payment Verification':'Payment under verification',Confirmed:'Order confirmed',Processing:'Preparing your parcel',Packed:'Parcel packed',Shipped:'Parcel handed to courier','Out for Delivery':'Out for delivery',Delivered:'Delivered',Cancelled:'Order cancelled',Returned:'Return accepted',Refunded:'Refund completed'} as any)[b.status]||b.status,`Order status changed to ${b.status}.`).run();if(old.user_id){await c.env.DB.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(old.user_id,'Order update',`Your order ${old.order_number} is now ${b.status}.`).run();if(b.status==='Delivered'){const pending=(await c.env.DB.prepare("SELECT 1 FROM reviews r JOIN order_items oi ON oi.product_id=r.product_id JOIN orders o ON o.id=oi.order_id WHERE o.id=? AND r.user_id=? LIMIT 1").bind(id,old.user_id).first());if(!pending)await c.env.DB.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(old.user_id,'Review your purchase',`Your order ${old.order_number} was delivered. You have 7 days to review your fragrance.`).run();}}await log(c,a,'update_status','order',String(id),old,b);return json({ok:true})});
app.patch('/api/admin/payments/:id/verify',async c=>{const a=await requireStaff(c,'payments');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id')),b=await c.req.json(),status=b.status==='Verified'?'Verified':'Rejected',reason=String(b.reason||b.note||'').trim();if(status==='Rejected'&&!reason)return json({error:'Please enter a rejection reason.'},400);const pay:any=await c.env.DB.prepare('SELECT * FROM payments WHERE id=?').bind(id).first();if(!pay)return json({error:'Payment not found'},404);await c.env.DB.prepare('UPDATE payments SET status=?,verified_by=?,verified_at=CURRENT_TIMESTAMP,note=?,rejection_reason=? WHERE id=?').bind(status,a.user.id,b.note||null,status==='Rejected'?reason:null,id).run();await c.env.DB.prepare('UPDATE orders SET payment_status=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(status,status==='Verified'?'Confirmed':'Payment Verification',pay.order_id).run();const ord:any=await c.env.DB.prepare('SELECT order_number,user_id FROM orders WHERE id=?').bind(pay.order_id).first();if(ord?.user_id)await c.env.DB.prepare('INSERT INTO notifications(user_id,title,body) VALUES(?,?,?)').bind(ord.user_id,status==='Verified'?'Payment verified':'Payment receipt rejected',status==='Verified'?`Your payment for ${ord.order_number} has been verified.`:`Your payment receipt for ${ord.order_number} was rejected. Reason: ${reason}`).run();await log(c,a,status==='Verified'?'approve_payment':'reject_payment','payment',String(id),pay,b);return json({ok:true})});
