app.post('/api/products/:id/view',async c=>{const id=Number(c.req.param('id'));const p=await c.env.DB.prepare('SELECT id FROM products WHERE id=? AND active=1').bind(id).first();if(!p)return json({error:'Product not found'},404);const u=await userFromReq(c);const guest=c.req.header('X-Cart-ID')||'';const ip=c.req.header('CF-Connecting-IP')||'';const viewer=await digest(`${u?.id||guest||ip}:${id}:${new Date().toISOString().slice(0,10)}`);await c.env.DB.prepare('INSERT OR IGNORE INTO product_views(product_id,viewer_key) VALUES(?,?)').bind(id,viewer).run();return json({ok:true})});
app.get('/api/products/:id/reviews',async c=>{const id=Number(c.req.param('id'));const rows=await c.env.DB.prepare("SELECT r.id,r.rating,r.body,r.verified_purchase,r.created_at,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? AND r.status='approved' ORDER BY r.id DESC").bind(id).all();const breakdown=await c.env.DB.prepare("SELECT rating,COUNT(*) count FROM reviews WHERE product_id=? AND status='approved' GROUP BY rating ORDER BY rating DESC").bind(id).all();return json({reviews:rows.results,breakdown:breakdown.results})});
