async function deliveryFee(c:any,quantity:number,subtotal:number,paymentMethod='cod'){const rules=(await c.env.DB.prepare('SELECT * FROM delivery_rules WHERE active=1 ORDER BY min_qty').all()).results as any[];const s=Object.fromEntries((await c.env.DB.prepare('SELECT key,value FROM settings').all()).results.map((r:any)=>[r.key,r.value]));let fee:number|undefined;for(const r of rules)if(quantity>=Number(r.min_qty)&&(r.max_qty==null||quantity<=Number(r.max_qty))){fee=Number(r.fee);break}if(fee===undefined){const free=Number(s.free_shipping_threshold||0);fee=free>0&&subtotal>=free?0:Number(s.delivery_fee||0)}if(paymentMethod==='cod')fee+=Math.max(0,Number(s.cod_delivery_advance||0));return fee}
app.post('/api/checkout/quote',async c=>{const b=await c.req.json().catch(()=>({}));const {row}=await cart(c);const items=(await c.env.DB.prepare('SELECT ci.quantity,p.price,p.sale_price,p.stock,p.min_quantity,p.max_quantity,v.id variant_id,v.name variant_name,v.price variant_price,v.sale_price variant_sale_price,v.stock variant_stock,v.active variant_active FROM cart_items ci JOIN products p ON p.id=ci.product_id LEFT JOIN product_variants v ON v.id=ci.variant_id WHERE ci.cart_id=? AND p.active=1').bind(row.id).all()).results as any[];if(!items.length)return json({error:'Cart is empty'},400);let subtotal=0,quantity=0;for(const i of items){const stock=Number(i.variant_id?i.variant_stock:i.stock);if(i.variant_id&&!i.variant_active)return json({error:'Selected size is no longer available'},409);if(i.quantity>stock)return json({error:'Selected quantity exceeds stock'},409);if(i.quantity<Number(i.min_quantity||1)||i.quantity>Number(i.max_quantity||99))return json({error:'Quantity limit exceeded'},409);const price=Number(i.variant_id?(i.variant_sale_price??i.variant_price):(i.sale_price??i.price));subtotal+=price*i.quantity;quantity+=i.quantity}let method=String(b.payment_method||'cod');if(method.startsWith('pm_')){const pm:any=await c.env.DB.prepare('SELECT method_type FROM payment_methods WHERE id=? AND active=1').bind(Number(method.slice(3))).first();if(pm?.method_type==='cod')method='cod'}const fee=await deliveryFee(c,quantity,subtotal,method);return json({subtotal,delivery_fee:fee,total:subtotal+fee,quantity,cod_delivery_advance:method==='cod'?Math.max(0,Number((await c.env.DB.prepare("SELECT value FROM settings WHERE key='cod_delivery_advance'").first() as any)?.value||0)):0})});
app.get('/api/admin/delivery-rules',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);return json({enabled:(await c.env.DB.prepare("SELECT value FROM settings WHERE key='delivery_rules_enabled'").first() as any)?.value==='1',rules:(await c.env.DB.prepare('SELECT * FROM delivery_rules ORDER BY min_qty').all()).results})});
app.post('/api/admin/delivery-rules',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);const b=await c.req.json(),min=Number(b.min_qty),max=b.max_qty===''||b.max_qty==null?null:Number(b.max_qty),fee=Number(b.fee);if(!Number.isInteger(min)||min<1||max!==null&&(max<min||!Number.isInteger(max))||fee<0)return json({error:'Invalid delivery rule'},400);const overlap=await c.env.DB.prepare('SELECT id FROM delivery_rules WHERE active=1 AND (? <= COALESCE(max_qty,1000000000) AND COALESCE(?,1000000000) >= min_qty)').bind(min,max).first();if(overlap)return json({error:'Delivery range overlaps an existing rule'},409);const r=await c.env.DB.prepare('INSERT INTO delivery_rules(min_qty,max_qty,fee) VALUES(?,?,?)').bind(min,max,fee).run();return json({id:r.meta.last_row_id},201)});
app.put('/api/admin/delivery-rules/:id',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id')),b=await c.req.json(),min=Number(b.min_qty),max=b.max_qty===''||b.max_qty==null?null:Number(b.max_qty),fee=Number(b.fee);if(!Number.isInteger(min)||min<1||max!==null&&(max<min||!Number.isInteger(max))||fee<0)return json({error:'Invalid delivery rule'},400);const overlap=await c.env.DB.prepare('SELECT id FROM delivery_rules WHERE active=1 AND id<>? AND (? <= COALESCE(max_qty,1000000000) AND COALESCE(?,1000000000) >= min_qty)').bind(id,min,max).first();if(overlap)return json({error:'Delivery range overlaps an existing rule'},409);await c.env.DB.prepare('UPDATE delivery_rules SET min_qty=?,max_qty=?,fee=?,active=? WHERE id=?').bind(min,max,fee,b.active===false?0:1,id).run();return json({ok:true})});
app.delete('/api/admin/delivery-rules/:id',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);await c.env.DB.prepare('DELETE FROM delivery_rules WHERE id=?').bind(Number(c.req.param('id'))).run();return json({ok:true})});
app.get('/api/admin/payment-methods',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);return json({payment_methods:(await c.env.DB.prepare('SELECT * FROM payment_methods ORDER BY display_order,id').all()).results})});
app.post('/api/admin/payment-methods',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);const b=await c.req.json();const r=await c.env.DB.prepare('INSERT INTO payment_methods(name,method_type,account_title,account_number,phone_number,bank_name,iban,instructions,qr_public_id,qr_url,active,display_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').bind(String(b.name),String(b.method_type||'online'),b.account_title||null,b.account_number||null,b.phone_number||null,b.bank_name||null,b.iban||null,b.instructions||null,b.qr_public_id||null,b.qr_url||null,b.active===false?0:1,Number(b.display_order||0)).run();return json({id:r.meta.last_row_id},201)});
app.put('/api/admin/payment-methods/:id',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id')),b=await c.req.json();const allowed=['name','method_type','account_title','account_number','phone_number','bank_name','iban','instructions','qr_public_id','qr_url','active','display_order'];const sets:string[]=[];const vals:any[]=[];for(const k of allowed)if(k in b){sets.push(`${k}=?`);vals.push(k==='active'?Number(!!b[k]):b[k])}if(!sets.length)return json({ok:true});await c.env.DB.prepare(`UPDATE payment_methods SET ${sets.join(',')} WHERE id=?`).bind(...vals,id).run();return json({ok:true})});
app.delete('/api/admin/payment-methods/:id',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);await c.env.DB.prepare('DELETE FROM payment_methods WHERE id=?').bind(Number(c.req.param('id'))).run();return json({ok:true})});
app.get('/api/admin/reviews',async c=>{const a=await requireStaff(c,'reviews');if('error'in a)return json({error:a.error},a.status);const q=c.req.query('q')||'',rating=Number(c.req.query('rating')||0),status=c.req.query('status')||'';let sql='SELECT r.*,p.name product_name,u.name customer_name,u.email FROM reviews r JOIN products p ON p.id=r.product_id JOIN users u ON u.id=r.user_id WHERE 1=1',p:any[]=[];if(q){sql+=' AND (r.body LIKE ? OR p.name LIKE ? OR u.name LIKE ? OR u.email LIKE ?)';const x=`%${q}%`;p.push(x,x,x,x)}if(rating){sql+=' AND r.rating=?';p.push(rating)}if(status){sql+=' AND r.status=?';p.push(status)}sql+=' ORDER BY r.id DESC LIMIT 500';return json({reviews:(await c.env.DB.prepare(sql).bind(...p).all()).results})});
app.patch('/api/admin/reviews/:id',async c=>{const a=await requireStaff(c,'reviews');if('error'in a)return json({error:a.error},a.status);const b=await c.req.json();await c.env.DB.prepare('UPDATE reviews SET status=? WHERE id=?').bind(b.status==='approved'?'approved':'hidden',Number(c.req.param('id'))).run();return json({ok:true})});
app.delete('/api/admin/reviews/:id',async c=>{const a=await requireStaff(c,'reviews');if('error'in a)return json({error:a.error},a.status);await c.env.DB.prepare('DELETE FROM reviews WHERE id=?').bind(Number(c.req.param('id'))).run();return json({ok:true})});
app.get('/api/admin/product-views',async c=>{const a=await requireStaff(c,'analytics');if('error'in a)return json({error:a.error},a.status);const rows=await c.env.DB.prepare('SELECT p.id,p.name,COUNT(v.id) total_views,COALESCE(SUM(CASE WHEN date(v.viewed_at)=date(\'now\') THEN 1 ELSE 0 END),0) today,COALESCE(SUM(CASE WHEN date(v.viewed_at)>=date(\'now\',\'-6 day\') THEN 1 ELSE 0 END),0) week,COALESCE(SUM(CASE WHEN strftime(\'%Y-%m\',v.viewed_at)=strftime(\'%Y-%m\',\'now\') THEN 1 ELSE 0 END),0) month FROM products p LEFT JOIN product_views v ON v.product_id=p.id GROUP BY p.id ORDER BY total_views DESC').all();return json({products:rows.results})});
app.get('/api/admin/analytics',async c=>{const a=await requireStaff(c,'analytics');if('error'in a)return json({error:a.error},a.status);const views=await c.env.DB.prepare('SELECT p.id,p.name,COUNT(v.id) views FROM products p LEFT JOIN product_views v ON v.product_id=p.id GROUP BY p.id ORDER BY views DESC LIMIT 10').all();const ratings=await c.env.DB.prepare("SELECT p.id,p.name,COALESCE(AVG(r.rating),0) rating,COUNT(r.id) review_count FROM products p LEFT JOIN reviews r ON r.product_id=p.id AND r.status='approved' GROUP BY p.id HAVING review_count>0 ORDER BY rating DESC,review_count DESC LIMIT 10").all();return json({most_viewed:views.results,top_rated:ratings.results})});
app.get('/api/admin/document-templates',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);return json({templates:(await c.env.DB.prepare('SELECT * FROM document_templates').all()).results})});
app.put('/api/admin/document-templates/:type',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);const type=c.req.param('type');if(!['invoice','awb'].includes(type))return json({error:'Invalid template type'},400);const b=await c.req.json();await c.env.DB.prepare('INSERT INTO document_templates(type,config,updated_at) VALUES(?,?,CURRENT_TIMESTAMP) ON CONFLICT(type) DO UPDATE SET config=excluded.config,updated_at=CURRENT_TIMESTAMP').bind(type,JSON.stringify(b.config||b)).run();return json({ok:true})});
app.get('/api/admin/order-sequence',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);return json({sequence:await c.env.DB.prepare('SELECT * FROM order_sequence WHERE id=1').first()})});
app.put('/api/admin/order-sequence',async c=>{const a=await requireStaff(c,'settings');if('error'in a)return json({error:a.error},a.status);const b=await c.req.json(),prefix=String(b.prefix||'SS-'),next=Number(b.next_number);if(!Number.isInteger(next)||next<1)return json({error:'Invalid starting number'},400);await c.env.DB.prepare('UPDATE order_sequence SET prefix=?,next_number=? WHERE id=1').bind(prefix,next).run();return json({ok:true})});
app.get('/api/admin/products/:id/variants',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);return json({variants:(await c.env.DB.prepare('SELECT * FROM product_variants WHERE product_id=? ORDER BY id').bind(Number(c.req.param('id'))).all()).results})});
app.post('/api/admin/products/:id/variants',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);const b=await c.req.json(),productId=Number(c.req.param('id')),name=String(b.name||'').trim(),price=Number(b.price);if(!name||!Number.isFinite(price)||price<0)return json({error:'Variant name and valid price are required'},400);const r=await c.env.DB.prepare('INSERT INTO product_variants(product_id,name,sku,price,sale_price,stock,weight,image_url,active) VALUES(?,?,?,?,?,?,?,?,?)').bind(productId,name,b.sku||null,price,b.sale_price===''?null:(b.sale_price??null),Number(b.stock||0),b.weight||null,b.image_url||null,b.active===false?0:1).run();await syncProductFromVariants(c,productId);return json({id:r.meta.last_row_id},201)});
app.put('/api/admin/products/:id/variants/:variantId',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);const b=await c.req.json(),id=Number(c.req.param('variantId')),productId=Number(c.req.param('id'));const allowed=['name','sku','price','sale_price','stock','weight','image_url','active'];const sets:string[]=[];const vals:any[]=[];for(const k of allowed)if(k in b){sets.push(`${k}=?`);vals.push(k==='active'?Number(!!b[k]):b[k]===''?null:b[k])}if(sets.length)await c.env.DB.prepare(`UPDATE product_variants SET ${sets.join(',')} WHERE id=? AND product_id=?`).bind(...vals,id,productId).run();await syncProductFromVariants(c,productId);return json({ok:true})});
app.delete('/api/admin/products/:id/variants/:variantId',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);const productId=Number(c.req.param('id'));await c.env.DB.prepare('DELETE FROM product_variants WHERE id=? AND product_id=?').bind(Number(c.req.param('variantId')),productId).run();await syncProductFromVariants(c,productId);return json({ok:true})});
app.delete('/api/admin/products/:id',async c=>{const a=await requireStaff(c,'products');if('error'in a)return json({error:a.error},a.status);const id=Number(c.req.param('id'));const p:any=await c.env.DB.prepare('SELECT id,name FROM products WHERE id=?').bind(id).first();if(!p)return json({error:'Product not found'},404);const ref:any=await c.env.DB.prepare('SELECT COUNT(*) n FROM order_items WHERE product_id=?').bind(id).first();if(Number(ref?.n||0)>0){await c.env.DB.prepare('UPDATE products SET active=0,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(id).run();await log(c,a,'archive','product',String(id),p,{reason:'Historical order references'});return json({ok:true,archived:true,message:'Product archived because it exists in historical orders.'})}await c.env.DB.prepare('DELETE FROM products WHERE id=?').bind(id).run();await log(c,a,'delete','product',String(id),p,null);return json({ok:true,deleted:true})});
app.post('/api/admin/banners/upload',async c=>{const a=await requireStaff(c,'content');if('error'in a)return json({error:a.error},a.status);const fd=await c.req.formData(),file=fd.get('file');if(!(file instanceof File))return json({error:'File required'},400);const kind=String(fd.get('kind')||'image');const up=await cloudinaryUpload(c,file,`shano-shan/banners`);return json({kind,url:up.secure_url,public_id:up.public_id})});
