app.put('/api/admin/banners/:id',async c=>{const a=await requireStaff(c,'content');if('error'in a)return json({error:a.error},a.status);const b=await c.req.json(),id=Number(c.req.param('id'));const allowed=['title','subtitle','cta_text','cta_url','desktop_url','mobile_url','video_url','start_at','end_at','active','sort_order','title_font','subtitle_font','cta_font','text_color','overlay_color','text_x','text_y','title_size','subtitle_size'];const sets:string[]=[];const vals:any[]=[];for(const k of allowed)if(k in b){sets.push(`${k}=?`);vals.push(k==='active'?Number(!!b[k]):b[k])}if(sets.length)await c.env.DB.prepare(`UPDATE banners SET ${sets.join(',')} WHERE id=?`).bind(...vals,id).run();return json({ok:true})});

